#!/usr/bin/env node
// Copy docs/roadmap.md from the repo root into the site as a
// top-level Starlight page. Adds the YAML frontmatter Starlight
// expects, strips the leading `# Roadmap` header (Starlight renders
// the title from frontmatter), and tags the output as
// auto-generated.

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..", "..");
const SRC = resolve(ROOT, "docs", "roadmap.md");
const OUT = resolve(HERE, "..", "src", "content", "docs", "roadmap.mdx");

const raw = readFileSync(SRC, "utf8");

// Strip the leading `# Roadmap` heading (Starlight uses frontmatter
// for the page title).
const body = raw
  .replace(/^#\s+Roadmap\s*\n+/, "")
  .trimEnd();

const front = [
  "---",
  "title: Roadmap",
  "description: What's shipped, what's in flight, and what's on the map.",
  "lastUpdated: " + new Date().toISOString(),
  "tableOfContents:",
  "  minHeadingLevel: 2",
  "  maxHeadingLevel: 3",
  "---",
  "",
  "{/* AUTO-GENERATED by site/scripts/sync-roadmap.mjs.",
  "    Visual overview at top is rendered from src/content/roadmap/roadmap.json",
  "    via the VisualRoadmap component. Prose narrative below is sourced from",
  "    docs/roadmap.md. DO NOT EDIT this file — edit the source(s) and rerun",
  "    `pnpm prebuild`. */}",
  "",
  'import VisualRoadmap from "../../components/VisualRoadmap.astro";',
  "",
  "{/* Visual roadmap is wide — give the timeline + cards room to breathe. */}",
  "<style is:global>{`",
  "  :root { --sl-content-width: min(88rem, calc(100% - 2rem)); }",
  "`}</style>",
  "",
  "<VisualRoadmap />",
  "",
  "## Detailed narrative",
  "",
  "_The structured visual above is rendered from the canonical JSON. The",
  "prose below is the human narrative — same content, more depth._",
  "",
].join("\n");

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, front + body + "\n", "utf8");
console.log(`[sync-roadmap] wrote ${OUT.replace(ROOT + "/", "")}`);
